3669	    async function startVoiceMeterV2(mode = "text") {
3670	      stopVoiceMeterV2();
3671	      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
3672	      const AudioContextCtor = window.AudioContext || window.webkitAudioContext;
3673	      if (!AudioContextCtor) {
3674	        stateV2.voiceStream = stream;
3675	        stateV2.voiceMode = mode;
3676	        return;
3677	      }
3678	      const audioContext = new AudioContextCtor();
3679	      const analyser = audioContext.createAnalyser();
3680	      analyser.fftSize = 256;
3681	      analyser.smoothingTimeConstant = 0.82;
3682	      const source = audioContext.createMediaStreamSource(stream);
3683	      source.connect(analyser);
3684	
3685	      stateV2.voiceAudioContext = audioContext;
3686	      stateV2.voiceAnalyser = analyser;
3687	      stateV2.voiceSource = source;
3688	      stateV2.voiceStream = stream;
3689	      stateV2.voiceMode = mode;
3690	      const buffer = new Uint8Array(analyser.fftSize);
3691	
3692	      const tick = () => {
3693	        if (!stateV2.voiceAnalyser) return;
3694	        analyser.getByteTimeDomainData(buffer);
3695	        let sum = 0;
3696	        for (let index = 0; index < buffer.length; index += 1) {
3697	          const value = (buffer[index] - 128) / 128;
3698	          sum += value * value;
3699	        }
3700	        const rms = Math.sqrt(sum / buffer.length);
3701	        const level = Math.max(0, Math.min(1, rms * 5.8));
3702	        stateV2.voiceMeterLevel = level;
3703	        renderVoiceMeterV2(level, stateV2.voiceMode);
3704	        dispatchAvatarEventV2("audioLevel", { level });
3705	        stateV2.voiceMeterRaf = window.requestAnimationFrame(tick);
3706	      };
3707	
3708	      tick();
3709	    }
